import re


_JOB_RE = re.compile(
    r"^JOB\s+(?P<name>\S+)\s+AT\s+(?P<at>\d{2}:\d{2})"
    r"\s+RUN\s+(?P<script>\S+)"
    r"(?:\s+ON_ERROR\s+(?P<on_error>ABORT|CONTINUE|RETRY:(?P<retries>\d+)))?$"
)


def parse_schedule(cfg_text: str) -> list[dict]:
    """Parse a Meridian CRM batch_jobs.cfg schedule in file order."""
    schedule = []

    for line_number, raw_line in enumerate(cfg_text.splitlines(), start=1):
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue

        match = _JOB_RE.fullmatch(line)
        if match is None:
            raise ValueError(f"invalid JOB line {line_number}: {raw_line!r}")

        clause = match.group("on_error")
        if clause is None or clause == "ABORT":
            on_error = {"policy": "ABORT", "retries": 0}
        elif clause == "CONTINUE":
            on_error = {"policy": "CONTINUE", "retries": 0}
        else:
            on_error = {
                "policy": "RETRY",
                "retries": int(match.group("retries")),
            }

        schedule.append(
            {
                "name": match.group("name"),
                "at": match.group("at"),
                "script": match.group("script"),
                "on_error": on_error,
            }
        )

    return schedule
